CREATE DATABASE IF NOT EXISTS smart_agriculture CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE smart_agriculture;
CREATE TABLE IF NOT EXISTS farms(id BIGINT PRIMARY KEY AUTO_INCREMENT,name VARCHAR(120) NOT NULL,location VARCHAR(255),area_acres DECIMAL(10,2),soil_type VARCHAR(80),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS crops(id BIGINT PRIMARY KEY AUTO_INCREMENT,farm_id BIGINT NOT NULL,crop_name VARCHAR(100),variety VARCHAR(100),sowing_date DATE,status VARCHAR(30),FOREIGN KEY(farm_id) REFERENCES farms(id));
CREATE TABLE IF NOT EXISTS soil_readings(id BIGINT PRIMARY KEY AUTO_INCREMENT,farm_id BIGINT NOT NULL,ph DECIMAL(4,2),moisture DECIMAL(5,2),nitrogen DECIMAL(8,2),phosphorus DECIMAL(8,2),potassium DECIMAL(8,2),recorded_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(farm_id) REFERENCES farms(id));
CREATE TABLE IF NOT EXISTS irrigation_schedules(id BIGINT PRIMARY KEY AUTO_INCREMENT,farm_id BIGINT NOT NULL,scheduled_at DATETIME,water_litres DECIMAL(12,2),notes VARCHAR(500),status VARCHAR(30),FOREIGN KEY(farm_id) REFERENCES farms(id));
CREATE TABLE IF NOT EXISTS harvest_records(id BIGINT PRIMARY KEY AUTO_INCREMENT,farm_id BIGINT NOT NULL,crop_name VARCHAR(100),harvest_date DATE,actual_yield_kg DECIMAL(12,2),sale_price_per_kg DECIMAL(10,2),FOREIGN KEY(farm_id) REFERENCES farms(id));
CREATE TABLE IF NOT EXISTS expenses(id BIGINT PRIMARY KEY AUTO_INCREMENT,farm_id BIGINT NOT NULL,category VARCHAR(80),amount DECIMAL(12,2),expense_date DATE,notes VARCHAR(500),FOREIGN KEY(farm_id) REFERENCES farms(id));
